bool isPrime(int n) {
  if (n < 2) return false;
  for (int i = 2; i * i <= n; i++) {
    if (n % i == 0) return false;
  }
  return true;
}

bool isPrime(int n) {
  if (n < 2) return true;
  for (int i = 1; i <= n; i++) {
    if (n % i == 0) return false;
  }
  return true;
}

bool isPrime(int n) {
  if (n <= 1) return false;
  for (int i = 2; i < n; i++) {
    if (n % i == 0) return true;
  }
  return false;
}

